raw_chrome.base_css:
*, ::before, ::after{box-sizing: border-box; margin: 0px; padding: 0px;}
:root{--amber: oklch(85% 0.1 45); --amber-glow: oklch(80% 0.12 42 / 0.4); --rose: oklch(75% 0.1 340); --rose-glow: oklch(75% 0.1 340 / 0.25); --sage: oklch(72% 0.08 160); --sage-glow: oklch(72% 0.08 160 / 0.2); --pearl: oklch(96% 0.02 80); --deep: oklch(12% 0.02 260); --midnight: oklch(8% 0.015 260); --text-primary: oklch(94% 0.01 60); --text-secondary: oklch(78% 0.02 50); --text-muted: oklch(60% 0.02 50); --glass-bg: oklch(18% 0.03 260 / 0.55); --glass-border: oklch(85% 0.05 60 / 0.12); --glass-border-hover: oklch(85% 0.08 45 / 0.3); --serif: 'DM Serif Display',serif; --serif-alt: 'Instrument Serif',serif; --sans: 'Syne',sans-serif; --data: 'Space Grotesk',sans-serif;}
html{scroll-behavior: smooth; overflow-x: hidden;}
body{background: var(--midnight); color: var(--text-primary); font-family: var(--sans); min-height: 100vh; overflow-x: hidden; cursor: none;}
::-webkit-scrollbar{width: 3px;}
::-webkit-scrollbar-track{background: transparent;}
::-webkit-scrollbar-thumb{background: oklch(0.85 0.08 45 / 0.4); border-radius: 99px;}
nav{position: fixed; top: 0px; left: 0px; right: 0px; z-index: 100; padding: 1.75rem 4rem; display: flex; align-items: center; justify-content: space-between; transition: background 0.5s, backdrop-filter 0.5s;}
footer{padding: 3rem 4rem; display: flex; align-items: center; justify-content: space-between; border-top: 1px solid var(--glass-border);}

raw_chrome.util_css:
.cursor{position: fixed; width: 12px; height: 12px; background: var(--amber); border-radius: 50%; pointer-events: none; z-index: 9999; transform: translate(-50%, -50%); transition: transform 0.1s, width 0.3s, height 0.3s, opacity 0.3s; mix-blend-mode: screen;}
.cursor-trail{position: fixed; width: 40px; height: 40px; border: 1px solid oklch(0.85 0.1 45 / 0.3); border-radius: 50%; pointer-events: none; z-index: 9998; transform: translate(-50%, -50%); transition: transform 0.25s, width 0.4s, height 0.4s;}
.hero{position: relative; height: 100vh; overflow: hidden; display: flex; align-items: center; justify-content: center;}
.video-portal{position: absolute; inset: 0px; z-index: 0;}
.video-portal video{width: 100%; height: 100%; object-fit: cover; filter: brightness(0.75);}
.video-portal::after{content: ""; position: absolute; inset: 0px; background: radial-gradient(ellipse 80% 100% at 50% 60%,transparent 45%,var(--midnight) 92%); pointer-events: none;}
.atmospheric-mask{position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 75vw; height: 65vh; z-index: 1; border-radius: 60% 40% 55% 45% / 45% 55% 40% 60%; mask-image: radial-gradient(85% 85%, black 40%, transparent 75%); animation: 18s ease-in-out 0s infinite normal none running blob-drift; overflow: hidden;}
.atmospheric-mask video{width: 130%; height: 130%; object-fit: cover; margin: -15%;}
@keyframes blob-drift { 
  0%, 100% { border-radius: 60% 40% 55% 45% / 45% 55% 40% 60%; transform: translate(-50%, -50%) scale(1); }
  33% { border-radius: 40% 60% 45% 55% / 55% 40% 65% 35%; transform: translate(-50%, -50%) scale(1.03); }
  66% { border-radius: 55% 45% 60% 40% / 40% 65% 35% 60%; transform: translate(-50%, -50%) scale(0.97); }
}
.light-corridor{position: absolute; inset: 0px; z-index: 2; pointer-events: none; background: radial-gradient(oklch(0.85 0.08 30 / 0.18) 0%, oklch(0.75 0.1 340 / 0.07) 40%, transparent 80%);}
.hero-content{position: relative; z-index: 10; text-align: center; max-width: 900px; padding: 0px 2rem;}
.hero-eyebrow{font-family: var(--data); font-size: 0.72rem; font-weight: 400; letter-spacing: 0.35em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 2rem; opacity: 0; animation: 1.2s ease 0.4s 1 normal forwards running fade-rise;}
.hero-title{font-family: var(--serif); font-size: clamp(3.2rem, 8vw, 8rem); line-height: 0.9; margin-bottom: 1.5rem; opacity: 0; animation: 1.4s ease 0.6s 1 normal forwards running fade-rise;}
.hero-title em{font-style: italic; color: var(--amber); display: block;}
.hero-subtitle{font-family: var(--data); font-size: 0.9rem; font-weight: 300; color: var(--text-secondary); letter-spacing: 0.08em; max-width: 480px; margin: 0px auto 3rem; line-height: 1.7; opacity: 0; animation: 1.4s ease 0.9s 1 normal forwards running fade-rise;}
.hero-cta-group{display: flex; align-items: center; justify-content: center; gap: 1.5rem; opacity: 0; animation: 1.2s ease 1.2s 1 normal forwards running fade-rise;}
@keyframes shimmer-spin { 
  100% { transform: rotate(360deg); }
}
.btn-ghost{padding: 1rem 2rem; background: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; color: var(--text-muted); font-family: var(--data); font-size: 0.82rem; letter-spacing: 0.12em; text-transform: uppercase; cursor: none; transition: color 0.3s; text-decoration: none;}
.btn-ghost:hover{color: var(--text-secondary);}
@keyframes fade-rise { 
  0% { opacity: 0; transform: translateY(30px); }
  100% { opacity: 1; transform: translateY(0px); }
}
.scroll-hint{position: absolute; bottom: 3rem; left: 50%; transform: translateX(-50%); z-index: 10; display: flex; flex-direction: column; align-items: center; gap: 0.75rem; opacity: 0; animation: 1s ease 2s 1 normal forwards running fade-rise;}
.scroll-hint span{font-family: var(--data); font-size: 0.65rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--text-muted);}
.scroll-line{width: 1px; height: 48px; background: linear-gradient(to bottom,var(--amber-glow),transparent); animation: 2s ease-in-out 0s infinite normal none running scroll-pulse;}
@keyframes scroll-pulse { 
  0%, 100% { opacity: 0.3; transform: scaleY(1); }
  50% { opacity: 1; transform: scaleY(1.2); }
}
.section-divider{height: 1px; background: radial-gradient(60% 100%, oklch(0.85 0.1 45 / 0.4), transparent); margin: 0px 8vw;}
section{padding: 8rem 0px;}
.container{max-width: 1320px; margin: 0px auto; padding: 0px 4rem;}
.section-label{font-family: var(--data); font-size: 0.65rem; letter-spacing: 0.4em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 1rem;}
.manifesto{background: transparent; position: relative;}
.manifesto::before{content: ""; position: absolute; top: 0px; left: 50%; transform: translateX(-50%); width: 70vw; height: 100%; background: radial-gradient(100% 80% at 50% 30%, oklch(0.85 0.08 45 / 0.06), transparent 70%); pointer-events: none;}
.manifesto-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8rem; align-items: center;}
.manifesto-text h2{font-family: var(--serif); font-size: clamp(2.4rem, 4vw, 4.2rem); line-height: 1.05; margin-bottom: 2rem;}
.manifesto-text h2 em{font-style: italic; color: oklch(0.8 0.1 340);}
.manifesto-text p{font-family: var(--data); font-size: 0.92rem; font-weight: 300; line-height: 1.85; color: var(--text-secondary); margin-bottom: 1.5rem;}
.manifesto-metrics{display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem;}
.metric-orb{padding: 2.5rem 2rem; border-radius: 40% 60% 55% 45% / 50% 40% 60% 50%; background: var(--glass-bg); border: 1px solid var(--glass-border); backdrop-filter: blur(20px); text-align: center; transition: border-radius 0.8s, border-color 0.4s, transform 0.4s; animation-duration: ; animation-timing-function: ; animation-iteration-count: ; animation-direction: ; animation-fill-mode: ; animation-play-state: ; animation-name: ; animation-timeline: ; animation-range-start: ; animation-range-end: ; animation-delay: var(--delay,0s);}
.metric-orb:hover{border-radius: 60% 40% 45% 55% / 40% 60% 50%; border-color: oklch(0.85 0.1 45 / 0.35); transform: translateY(-4px);}
@keyframes float-orb { 
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-8px); }
}
.metric-value{font-family: var(--serif); font-size: 3rem; color: var(--amber); line-height: 1; margin-bottom: 0.5rem;}
.metric-label{font-family: var(--data); font-size: 0.72rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--text-muted);}
.pillars{padding: 8rem 0px; position: relative;}
.pillars::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(80% 60% at 20% 50%, oklch(0.72 0.08 160 / 0.06), transparent 60%), radial-gradient(60% 80% at 80% 60%, oklch(0.75 0.1 340 / 0.05), transparent 60%); pointer-events: none;}
.pillars-header{text-align: center; margin-bottom: 5rem;}
.pillars-header h2{font-family: var(--serif); font-size: clamp(2rem, 3.5vw, 3.5rem); line-height: 1.1;}
.pillars-header h2 em{font-style: italic; color: var(--sage);}
.pillars-header p{font-family: var(--data); font-size: 0.9rem; font-weight: 300; color: var(--text-muted); max-width: 500px; margin: 1.5rem auto 0px; line-height: 1.7;}
.pillars-flow{display: grid; grid-template-columns: repeat(4, 1fr); gap: 0px; position: relative;}
.pillar-card{padding: 3rem 2rem; position: relative; border-radius: 40% 60% 70% 30% / 40% 50% 60%; background: oklch(0.16 0.02 260 / 0.6); border: 1px solid var(--glass-border); margin: 0.75rem; backdrop-filter: blur(16px); transition: border-radius 0.9s, transform 0.4s, background 0.4s, border-color 0.4s; overflow: hidden;}
.pillar-card::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at 50% 0%,var(--card-glow,oklch(85% 0.1 45 / 0.1)) 0%,transparent 60%); opacity: 0; transition: opacity 0.4s;}
.pillar-card:hover{border-radius: 60% 40% 30% 70% / 50% 60% 40% 50%; transform: translateY(-8px) rotate(-0.5deg); background: oklch(0.18 0.03 260 / 0.75); border-color: var(--glass-border-hover);}
.pillar-card:hover::before{opacity: 1;}
.pillar-card:nth-child(2){--card-glow: oklch(72% 0.08 160 / 0.12);}
.pillar-card:nth-child(3){--card-glow: oklch(75% 0.1 340 / 0.1);}
.pillar-card:nth-child(4){--card-glow: oklch(75% 0.12 250 / 0.1);}
.pillar-icon{width: 48px; height: 48px; margin-bottom: 1.75rem; border-radius: 50%; background: oklch(0.85 0.08 45 / 0.08); border: 1px solid var(--glass-border); display: flex; align-items: center; justify-content: center;}
.pillar-icon svg{width: 22px; height: 22px; stroke: var(--amber); fill: none; stroke-width: 1.5;}
.pillar-card:nth-child(2) .pillar-icon svg{stroke: var(--sage);}
.pillar-card:nth-child(3) .pillar-icon svg{stroke: oklch(0.75 0.1 340);}
.pillar-card:nth-child(4) .pillar-icon svg{stroke: oklch(0.72 0.1 250);}
.pillar-tag{font-family: var(--data); font-size: 0.62rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 0.75rem;}
.pillar-title{font-family: var(--serif-alt); font-size: 1.4rem; margin-bottom: 1rem; color: var(--text-primary);}
.pillar-body{font-family: var(--data); font-size: 0.82rem; line-height: 1.8; color: var(--text-muted); font-weight: 300;}
.projects{padding: 8rem 0px; position: relative;}
.projects-header{display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 4rem;}
.projects-header h2{font-family: var(--serif); font-size: clamp(2.2rem, 3.5vw, 3.8rem); line-height: 1; max-width: 500px;}
.projects-header h2 em{font-style: italic; color: var(--amber);}
.projects-nav{display: flex; gap: 0.75rem;}
.proj-btn{width: 42px; height: 42px; border-radius: 50%; background: transparent; border: 1px solid var(--glass-border); color: var(--text-muted); cursor: none; display: flex; align-items: center; justify-content: center; transition: border-color 0.3s, background 0.3s, color 0.3s; font-size: 1.1rem;}
.proj-btn:hover{border-color: var(--glass-border-hover); background: oklch(0.85 0.08 45 / 0.08); color: var(--text-primary);}
.projects-track-wrapper{overflow: hidden;}
.projects-track{display: flex; gap: 1.5rem; transition: transform 0.7s cubic-bezier(0.4, 0, 0.2, 1);}
.project-card{flex: 0 0 calc(50% - 0.75rem); border-radius: 40% 60% 50% 50% / 50% 40% 60% 50%; overflow: hidden; position: relative; aspect-ratio: 16 / 10; transition: border-radius 0.9s, transform 0.5s; background: oklch(0.15 0.03 260); border: 1px solid var(--glass-border); cursor: none;}
.project-card:hover{border-radius: 55% 45% 40% 60% / 40% 60% 50% 50%; transform: scale(1.02);}
.project-bg{position: absolute; inset: 0px; background: var(--project-bg); filter: saturate(1.2) brightness(0.6); transition: filter 0.5s, transform 0.7s;}
.project-card:hover .project-bg{filter: saturate(1.4) brightness(0.7); transform: scale(1.05);}
.project-card:nth-child(1){--project-bg: radial-gradient(ellipse at 30% 60%,oklch(65% 0.15 160),oklch(20% 0.05 200));}
.project-card:nth-child(2){--project-bg: radial-gradient(ellipse at 70% 40%,oklch(60% 0.12 340),oklch(18% 0.04 280));}
.project-card:nth-child(3){--project-bg: radial-gradient(ellipse at 50% 70%,oklch(70% 0.1 45),oklch(20% 0.06 260));}
.project-card:nth-child(4){--project-bg: radial-gradient(ellipse at 40% 50%,oklch(55% 0.1 250),oklch(15% 0.04 280));}
.project-info{position: absolute; bottom: 0px; left: 0px; right: 0px; padding: 2.5rem; background: linear-gradient(to top, oklch(0.08 0.02 260 / 0.9) 0%, transparent 100%);}
.project-kv{font-family: var(--data); font-size: 0.62rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--amber); margin-bottom: 0.6rem;}
.project-title{font-family: var(--serif); font-size: 1.8rem; margin-bottom: 0.4rem;}
.project-loc{font-family: var(--data); font-size: 0.78rem; color: var(--text-muted); letter-spacing: 0.08em;}
.data-strip{padding: 5rem 0px; position: relative; overflow: hidden;}
.data-strip::before{content: ""; position: absolute; inset: 0px; background: oklch(0.14 0.025 260 / 0.8); backdrop-filter: blur(2px);}
.data-strip::after{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: radial-gradient(50% 100% at 50% 0%, oklch(0.85 0.1 45 / 0.3), transparent);}
.data-row{position: relative; z-index: 1; display: grid; grid-template-columns: repeat(5, 1fr); gap: 1px;}
.data-cell{padding: 2.5rem 2rem; text-align: center; border-right: 1px solid var(--glass-border); position: relative;}
.data-cell:last-child{border-right-width: medium; border-right-style: none; border-right-color: currentcolor;}
.data-cell-num{font-family: var(--serif); font-size: 2.8rem; color: var(--text-primary); line-height: 1; margin-bottom: 0.4rem;}
.data-cell-num span{font-size: 1.4rem; color: var(--amber);}
.data-cell-label{font-family: var(--data); font-size: 0.65rem; letter-spacing: 0.25em; text-transform: uppercase; color: var(--text-muted);}
.philosophy{padding: 8rem 0px; position: relative;}
.philosophy::before{content: ""; position: absolute; right: -20%; top: 10%; width: 60vw; height: 60vw; border-radius: 50%; background: radial-gradient(circle, oklch(0.75 0.1 340 / 0.04) 0%, transparent 65%); pointer-events: none;}
.philosophy-inner{display: grid; grid-template-columns: 2fr 3fr; gap: 8rem; align-items: start;}
.philosophy-sticky{position: sticky; top: 10rem;}
.philosophy-sticky h2{font-family: var(--serif); font-size: clamp(2rem, 3vw, 3.2rem); line-height: 1.05; margin-bottom: 2rem;}
.philosophy-sticky h2 em{font-style: italic; color: oklch(0.8 0.1 340);}
.philosophy-sticky p{font-family: var(--data); font-size: 0.85rem; font-weight: 300; line-height: 1.8; color: var(--text-secondary); margin-bottom: 2.5rem;}
.phil-line-item{display: flex; gap: 1.25rem; align-items: start; padding: 2rem 0px; border-top: 1px solid var(--glass-border); position: relative;}
.phil-line-item::after{content: ""; position: absolute; top: 0px; left: 0px; right: 0px; height: 1px; background: radial-gradient(30% 100% at 50% 0%, oklch(0.85 0.1 45 / 0.25), transparent);}
.phil-number{font-family: var(--serif-alt); font-size: 1rem; color: var(--amber); font-style: italic; min-width: 2rem; margin-top: 0.1rem;}
.phil-content h3{font-family: var(--sans); font-size: 1rem; font-weight: 600; margin-bottom: 0.5rem; letter-spacing: 0.02em;}
.phil-content p{font-family: var(--data); font-size: 0.82rem; line-height: 1.75; color: var(--text-muted); font-weight: 300;}
.ecology-ticker{padding: 2.5rem 0px; overflow: hidden; position: relative; border-top: 1px solid var(--glass-border); border-bottom: 1px solid var(--glass-border);}
.ecology-ticker::before, .ecology-ticker::after{content: ""; position: absolute; top: 0px; bottom: 0px; width: 15vw; z-index: 2;}
.ecology-ticker::before{left: 0px; background: linear-gradient(to right,var(--midnight),transparent);}
.ecology-ticker::after{right: 0px; background: linear-gradient(to left,var(--midnight),transparent);}
.ticker-inner{display: flex; gap: 4rem; animation: 30s linear 0s infinite normal none running ticker; white-space: nowrap;}
.ticker-item{display: flex; align-items: center; gap: 1rem; font-family: var(--data); font-size: 0.75rem; letter-spacing: 0.2em; text-transform: uppercase; color: var(--text-muted);}
.ticker-dot{width: 5px; height: 5px; border-radius: 50%; background: var(--amber); flex-shrink: 0;}
@keyframes ticker { 
  0% { transform: translateX(0px); }
  100% { transform: translateX(-50%); }
}
.contact-section{padding: 10rem 0px 8rem; position: relative; text-align: center;}
.contact-section::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(80% 100%, oklch(0.85 0.08 45 / 0.05), transparent 70%);}
.contact-eyebrow{font-family: var(--data); font-size: 0.68rem; letter-spacing: 0.4em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 1.5rem;}
.contact-h{font-family: var(--serif); font-size: clamp(3rem, 6vw, 6.5rem); line-height: 0.95; margin-bottom: 2.5rem; position: relative; z-index: 1;}
.contact-h em{font-style: italic; color: var(--amber);}
.contact-sub{font-family: var(--data); font-size: 0.9rem; color: var(--text-muted); max-width: 420px; margin: 0px auto 3.5rem; line-height: 1.7; font-weight: 300;}
.contact-form{max-width: 560px; margin: 0px auto; display: grid; gap: 1rem; position: relative; z-index: 1;}
.input-shell{position: relative;}
.input-shell input, .input-shell textarea{width: 100%; padding: 1.2rem 1.75rem; border-radius: 40% 60% 70% 30% / 40% 50% 60%; background: oklch(0.16 0.025 260 / 0.6); border: 1px solid var(--glass-border); color: var(--text-primary); font-family: var(--data); font-size: 0.88rem; outline: none; transition: border-radius 0.6s, border-color 0.3s, background 0.3s; backdrop-filter: blur(10px);}
.input-shell textarea{resize: none; height: 120px; border-radius: 30% 70% 50% 50% / 50% 30% 70% 50%;}
.input-shell input::placeholder, .input-shell textarea::placeholder{color: var(--text-muted); letter-spacing: 0.08em; font-size: 0.82rem;}
.input-shell input:focus{border-radius: 60% 40% 30% 70% / 50% 60% 40%; border-color: oklch(0.85 0.1 45 / 0.4); background: oklch(0.18 0.03 260 / 0.7);}
.input-shell textarea:focus{border-radius: 50% 50% 60% 40% / 40% 60% 50% 50%; border-color: oklch(0.85 0.1 45 / 0.4); background: oklch(0.18 0.03 260 / 0.7);}
.breeze-word{display: inline-block; transition: transform 0.1s;}
.reveal-up{opacity: 0; transform: translateY(40px); transition: opacity 0.9s, transform 0.9s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal-up.visible{opacity: 1; transform: none;}
.ambient-orbs{position: fixed; inset: 0px; pointer-events: none; z-index: 0; overflow: hidden;}
.amb-orb{position: absolute; border-radius: 50%; filter: blur(80px); animation-duration: ; animation-timing-function: ; animation-iteration-count: ; animation-direction: ; animation-fill-mode: ; animation-play-state: ; animation-name: ; animation-timeline: ; animation-range-start: ; animation-range-end: ; animation-delay: var(--delay);}
@keyframes orb-drift { 
  0%, 100% { transform: translate(0px, 0px); }
  33% { transform: translate(var(--dx1),var(--dy1)); }
  66% { transform: translate(var(--dx2),var(--dy2)); }
}
.preloader{position: fixed; inset: 0px; z-index: 9999; background: var(--midnight); display: flex; align-items: center; justify-content: center; transition: opacity 0.8s;}
.preloader.hidden{opacity: 0; pointer-events: none;}
.pre-logo{font-family: var(--serif); font-size: 2rem; animation: 1.5s ease-in-out 0s infinite normal none running pre-pulse;}
.pre-logo em{color: var(--amber); font-style: italic;}
@keyframes pre-pulse { 
  0%, 100% { opacity: 0.3; }
  50% { opacity: 1; }
}
.grain-overlay{position: fixed; inset: 0px; z-index: 1; pointer-events: none; opacity: 0.025; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(https://openhero.art/api/%23n)'/%3E%3C/svg%3E"); background-size: 200px 200px;}

raw_chrome.header_css:
.btn-liquid{position: relative; padding: 1rem 2.5rem; border-radius: 40% 60% 70% 30% / 40% 50% 60%; border: 1px solid var(--glass-border-hover); background: oklch(0.85 0.08 45 / 0.08); color: var(--text-primary); font-family: var(--data); font-size: 0.82rem; letter-spacing: 0.15em; text-transform: uppercase; cursor: none; overflow: hidden; transition: border-radius 0.6s, border-color 0.3s, background 0.3s; text-decoration: none; display: inline-flex; align-items: center; gap: 0.75rem;}
.btn-liquid::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at var(--mx,50%) var(--my,50%),oklch(85% 0.1 45 / 0.25) 0%,transparent 60%); opacity: 0; transition: opacity 0.3s;}
.btn-liquid::after{content: ""; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%; background: conic-gradient(transparent 30%, oklch(0.85 0.1 45 / 0.15) 40%, transparent 50%); animation: 4s linear 0s infinite normal none running shimmer-spin; opacity: 0; transition: opacity 0.4s;}
.btn-liquid:hover{border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; border-color: oklch(0.85 0.1 45 / 0.5); background: oklch(0.85 0.08 45 / 0.15);}
.btn-liquid:hover::before, .btn-liquid:hover::after{opacity: 1;}
.nav-logo{font-family: var(--serif); font-size: 1.2rem; color: var(--text-primary); letter-spacing: 0.02em; text-decoration: none;}
.nav-logo span{color: var(--amber);}
.nav-links{display: flex; align-items: center; gap: 3rem; list-style: none;}
.nav-links a{font-family: var(--data); font-size: 0.75rem; letter-spacing: 0.2em; text-transform: uppercase; color: var(--text-muted); text-decoration: none; transition: color 0.3s; position: relative;}
.nav-links a::after{content: ""; position: absolute; bottom: -4px; left: 0px; right: 0px; height: 1px; background: var(--amber); transform: scaleX(0); transform-origin: left center; transition: transform 0.3s;}
.nav-links a:hover{color: var(--text-primary);}
.nav-links a:hover::after{transform: scaleX(1);}

raw_chrome.footer_css:
