.footer-links a{font-family: var(--data); font-size: 0.7rem; letter-spacing: 0.15em; text-transform: uppercase; color: oklch(0.4 0.01 60); text-decoration: none; transition: color 0.3s;}
.footer-links a:hover{color: var(--text-muted);}
